pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the block timestamp to decide the behaviour
    function testFuzz_property(address caller, uint256 ts) public {
        // admissible caller: non-zero
        vm.assume(caller != address(0));
        // bound timestamp to plausible Ethereum timestamps
        ts = bound(ts, 0, type(uint64).max);

        // Ensure caller has funds to send 10 ether
        vm.deal(caller, 20 ether);

        // Arrange: set pastBlockTime to current block.timestamp (so equal)
        // We warp to a chosen base time and set pastBlockTime by making a valid fallback call once with increased time.
        vm.warp(1);
        vm.prank(caller);
        c.f{value: 10 ether}(); // should succeed and set pastBlockTime = 1

        // Now set block timestamp to ts for the decisive call
        vm.warp(ts);

        // Attempt the decisive call; capture whether it reverts
        bool ok;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: If the call does NOT revert on the reference implementation,
        // then pastBlockTime must be strictly less than the new block.timestamp (i.e., it was updated to ts only when ts > previous)
        // We observe this by reading the public getter pastBlockTime.
        uint256 observed = c.pastBlockTime();

        // For the reference contract: when the call succeeds, it must have set pastBlockTime == ts and therefore ts > previous (previous was 1)
        // We assert that whenever the call succeeded, observed == ts and ts > 1
        // This property is satisfied by the correct contract for all inputs, but the mutant that removed the time check can succeed even when ts <= previous (e.g., ts == 1), updating pastBlockTime to a non-increasing value, so the assertion will fail for some inputs.
        if (ok) {
            assertTrue(observed == ts && ts > 1);
        } else {
            // If the call reverted, the reference contract also reverts for those inputs; no further assertion needed.
            assertTrue(observed == 1);
        }
    }
}

