pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address and an initial timestamp delta to control block time progression.
    // We will perform two calls from the same caller with the same timestamp (no forward warp)
    // The correct contract requires block.timestamp > pastBlockTime to update; thus the second
    // call should NOT change pastBlockTime. The mutant (which removed the time check) WILL
    // update pastBlockTime on the second call, so observing that pastBlockTime stayed equal
    // after the second call is the universal property the reference satisfies and the mutant
    // can violate for some inputs.
    function testFuzz_property(address caller, uint96 initialTimeWarp) public {
        // keep caller non-zero
        vm.assume(caller != address(0));

        // Fund the caller so they can send 10 ether
        vm.deal(caller, 20 ether);

        // Ensure initialTimeWarp is within a reasonable range so warp works
        uint256 warpAmount = uint256(initialTimeWarp) % 100000; // keep within large window

        // Warp to a starting time
        vm.warp(block.timestamp + warpAmount);

        // First call: should succeed and set pastBlockTime = block.timestamp
        vm.prank(caller);
        c.f{value: 10 ether}();
        uint256 t1 = c.pastBlockTime();

        // Do NOT advance time: second call happens at same timestamp
        // Call again from same caller with 10 ether
        vm.prank(caller);
        c.f{value: 10 ether}();
        uint256 t2 = c.pastBlockTime();

        // General rule: for the correct contract, if a second fallback call occurs at the same
        // block.timestamp as the first, pastBlockTime must remain unchanged (t2 == t1).
        // The mutant that removed the time check can update pastBlockTime on the second call,
        // making t2 != t1 for some inputs; hence assert equality.
        assertTrue(t2 == t1);
    }
}

