pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and a timestamp delta (can be zero) to try to produce a non-increasing timestamp
    function testFuzz_property(address caller, uint64 dt) public {
        // keep caller non-zero EOA-ish
        vm.assume(caller != address(0));

        // start with an initial call at some time
        vm.warp(1000);
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        // first call sets pastBlockTime to 1000 in the reference
        c.f{value: 10 ether}();

        // compute next timestamp: allow dt to be large so we can both increase and not increase
        // we want to sometimes produce a non-increasing timestamp: pick nextTime = 1000 + (dt % 2 == 0 ? 0 : (dt % 10000))
        // but we cannot use complex expressions to bias; instead use parity to produce equal timestamp when dt is even
        uint64 nextTime = 1000 + (dt % 2 == 0 ? 0 : uint64(dt % 10000));
        vm.warp(nextTime);

        vm.deal(caller, 20 ether);
        vm.prank(caller);
        // second call may or may not update pastBlockTime depending on contract version and timestamp
        c.f{value: 10 ether}();

        // The universal property: after any two sequential valid fallback calls (each with exactly 10 ether), the reference C's pastBlockTime is >= the previous stored value and only strictly increases if block.timestamp was strictly greater; in particular, it never decreases. We assert that pastBlockTime is >= 1000 (the initial value set), which holds for the reference for all admissible inputs; the mutant may have updated it differently when timestamp is not greater, but cannot make it < 1000, so we instead assert the stronger distinguishing property: after the second call at a non-increasing timestamp (when nextTime == 1000) the reference will still have pastBlockTime == 1000, while the mutant could change it — we encode a universal check the reference satisfies by observing the getter.
        // To make this a single assertTrue reading c: check that c.pastBlockTime() >= 1000 which the reference always satisfies for any inputs here.
        // This single assertion is true for the reference on all inputs; the mutant can violate the intended behavioral rule (it can set pastBlockTime even when timestamp not greater), but it will not make pastBlockTime < 1000, so to ensure the test fails on the mutant for some inputs we rely on the fuzzer finding a case where nextTime == 1000 and the mutant changes pastBlockTime to equal block.timestamp (still 1000) — however that would not fail this >= check. To make the test fail on the mutant for some input, we instead assert that if we called at the same timestamp (nextTime == 1000) then pastBlockTime remained unchanged (==1000). We can read block.timestamp to know whether we are in that case; produce a single assertTrue that is universally true on the reference: if block.timestamp == 1000 then c.pastBlockTime() == 1000.

        if (block.timestamp == 1000) {
            assertTrue(c.pastBlockTime() == 1000);
        } else {
            // when timestamp advanced, pastBlockTime must be >= previous (1000)
            assertTrue(c.pastBlockTime() >= 1000);
        }
    }
}

