        // but we will always send exactly 10 ether in the call below
        vm.deal(caller, 20 ether);

        // record the initial stored pastBlockTime
        uint256 before = c.pastBlockTime();

        // warp to the chosen timestamp
        vm.warp(ts);

        // perform the payable low-level invocation via normal external payable call to fallback
        // using exactly 10 ether as required by the contract
        bool ok;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            ok = true;
