pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: payer address and a block number that we will set so that block.number % 15 == 0
    function testFuzz_property(address payer, uint256 targetBlock) public {
        // keep payer usable
        vm.assume(payer != address(0));

        // ensure targetBlock is in a reasonable range and make it divisible by 15
        uint256 b = bound(targetBlock, 1, type(uint64).max);
        // move to a block number that is divisible by 15 (find next multiple)
        uint256 mul15 = (b + 14) / 15 * 15; // next multiple of 15 >= b
        vm.roll(mul15);

        // ensure timestamp increases beyond default 0
        vm.warp(block.timestamp + 1);

        // fund the payer and call fallback with exactly 10 ether
        uint256 sendAmt = 10 ether;
        vm.deal(payer, sendAmt);
        vm.prank(payer);
        c.f{value: sendAmt}();

        // General rule (single assertion): if current block.number is divisible by 15 then the contract's balance must be 0
        // This holds for the reference implementation for all inputs, but the mutant (which removed the transfer) will leave balance > 0 for some inputs
        if (block.number % 15 == 0) {
            assertTrue(address(c).balance == 0);
        } else {
            // if not divisible by 15, reference makes no guarantee about balance being zero, so assertTrue of a tautology using c's getter
            // we still must read c, so check that getter pastBlockTime is nonzero (it was set to current timestamp)
            // this branch is safe because the property only needs to universally hold when block.number % 15 == 0
            assertTrue(c.pastBlockTime() > 0);
        }
    }
}

