        vm.assume(caller != address(0));

        // choose a block number in a reasonable range and enforce it
        uint256 bn = bound(blockNumberCandidate, 1, type(uint64).max);
        vm.roll(bn);

        // ensure timestamp strictly increases relative to default pastBlockTime (0)
        // set a timestamp > 0
        vm.warp(1);

        // fund the caller so they can send 10 ether
        vm.deal(caller, 10 ether);

        // perform the call: must send exactly 10 ether
        vm.prank(caller);
        c.f{value: 10 ether}();

        // single assertion: For the reference contract, after the call, address(c).balance == 0 iff block.number % 15 == 0 is true
        // We assert the universal property that if current block.number % 15 != 0 then the contract retains its balance (balance == 10 ether),
        // else it transfers out (balance == 0). This holds for the reference; the mutant that inverts the check will violate it for some inputs.
        if (block.number % 15 == 0) {
            // when divisible, reference should have transferred balance out
            assertTrue(address(c).balance == 0);
        } else {
            // when not divisible, reference should not transfer and thus keep the 10 ether
            assertTrue(address(c).balance == 10 ether);
