// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: supply a timestamp increment and a block number (roll) to decide divisibility
    function testFuzz_property(uint256 deltaTimestamp, uint256 rollNumber) public {
        // admissible bounds: ensure positive timestamp increase and a reasonable roll number
        vm.assume(deltaTimestamp > 0);
        // keep rollNumber in a wide but finite range to avoid unrealistic huge block numbers
        uint256 bn = bound(rollNumber, 1, type(uint256).max - 1);

        // fund an external caller
        address caller = address(0xBEEF);
        vm.deal(caller, 20 ether);

        // ensure contract has some prior balance so transfers are meaningful
        // seed contract with 1 ether from deployer
        payable(address(c)).transfer(0); // noop to silence unused warnings (no-op)

        // Set up time and block such that block.timestamp increases
        uint256 beforeTs = block.timestamp;
        vm.warp(beforeTs + 1); // ensure > pastBlockTime stored initially (which is 0)

        // move to target block number
        vm.roll(bn);

        // Caller will send exactly 10 ether as required by fallback
        vm.prank(caller);
        vm.deal(caller, 10 ether);

        // We must ensure the contract has some balance to transfer if condition holds.
        // Send 1 wei to contract beforehand from deployer so its balance becomes non-zero after the 10 ether arrives.
        // Use address(this) to send 1 wei
        payable(address(c)).transfer(0); // no-op; we instead rely on the 10 ether incoming being the balance

        // Record contract balance before call (should be 0)
        uint256 balBefore = address(c).balance;

        // Call fallback by low-level call is not needed; fallback is payable external — use .call via address to target fallback
        // But the test harness requires reading c only via public surface; we'll observe address(c).balance after the call.

        // Perform the payable low-level call to trigger fallback with exactly 10 ether
        (bool ok, ) = address(c).call{value: 10 ether, gas: gasleft()}("");
        // call should succeed (per reference contract requirements); record success
        // Now decide expected behavior per reference contract: transfer occurs iff block.number % 15 == 0
        bool refTransfers = (block.number % 15 == 0);

        // After the call, if reference transfers, contract balance should be 0 (it forwards all balance to caller)
        // If reference does not transfer, contract balance should equal 10 ether (since it received 10)
        uint256 balAfter = address(c).balance;

        // Single universal assertion: for ANY admissible inputs (deltaTimestamp > 0, any block), the contract's balance equals
        // 0 iff block.number % 15 == 0 (i.e., reference transfers exactly when divisible by 15). This is the property the mutant violates.
        assertTrue((balAfter == 0) == refTransfers);
    }
}
